INSERT IGNORE INTO `plantilla_whatsapp` (`id_plantilla`, `activo`, `categoria`, `codigo_meta`, `contenido`, `create_date`, `estado_meta`, `fecha_aprobacion`, `idioma`, `nombre`, `parametros`, `template_id`, `update_date`, `create_by`, `update_by`) VALUES (4,_binary '','UTILITY','factura_vencida','⚠️ Factura vencida\n\nHola {{1}},\n\nLa factura #{{2}} por {{3}} venció el {{4}}.\n\nPor favor, realiza el pago a la brevedad para evitar cargos adicionales.\n\n📞 ¿Necesitas ayuda? Contáctanos respondiendo este mensaje.',NULL,'APPROVED','2025-10-27 01:08:57.000000','es_CRI','factura_vencida','[\"nombre_cliente\", \"numero_factura\", \"monto\", \"fecha_vencimiento\"]',NULL,NULL,NULL,NULL);
